package com.farm2market.controller;
import com.farm2market.dto.*; import com.farm2market.entity.*; import com.farm2market.repository.*; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController {final ProductRepository products;final UserRepository users; ProductController(ProductRepository p,UserRepository u){products=p;users=u;} @GetMapping public Map<String,Object> all(){return Map.of("success",true,"data",products.findByActiveTrue());} @GetMapping("/{id}") public Product one(@PathVariable Long id){return products.findById(id).orElseThrow(()->new RuntimeException("Product not found"));} @GetMapping("/search") public Map<String,Object> search(@RequestParam String keyword){return Map.of("success",true,"data",products.findByNameContainingIgnoreCaseAndActiveTrue(keyword));} @GetMapping("/category/{category}") public Map<String,Object> cat(@PathVariable Category category){return Map.of("success",true,"data",products.findByCategoryAndActiveTrue(category));} @PostMapping @PreAuthorize("hasRole('FARMER')") public Product add(@Valid @RequestBody ProductRequest x,@AuthenticationPrincipal UserDetails auth){Product p=new Product();p.setFarmer(users.findByEmail(auth.getUsername()).orElseThrow());copy(p,x);return products.save(p);} @PutMapping("/{id}") @PreAuthorize("hasRole('FARMER')") public Product edit(@PathVariable Long id,@Valid @RequestBody ProductRequest x,@AuthenticationPrincipal UserDetails auth){Product p=one(id);if(!p.getFarmer().getEmail().equals(auth.getUsername()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"You do not own this product");copy(p,x);p.setUpdatedAt(java.time.LocalDateTime.now());return products.save(p);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('FARMER')") public Map<String,Object> delete(@PathVariable Long id,@AuthenticationPrincipal UserDetails auth){Product p=one(id);if(!p.getFarmer().getEmail().equals(auth.getUsername()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"You do not own this product");p.setActive(false);products.save(p);return Map.of("success",true,"message","Product removed");} void copy(Product p,ProductRequest x){p.setName(x.name());p.setCategory(x.category());p.setDescription(x.description());p.setPricePerKg(x.pricePerKg());p.setAvailableQuantity(x.availableQuantity());p.setUnit(x.unit()==null?"kg":x.unit());p.setMinimumOrderQuantity(x.minimumOrderQuantity());p.setQualityGrade(x.qualityGrade());p.setLocation(x.location());p.setImageUrl(x.imageUrl());}}
